#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

#define MAX_INPUT 0xBFA17DC6ULL
static const uint64_t small_primes[] = {2, 3, 5, 7, 11, 13};
static const uint64_t mr_bases[] = {2, 3, 5, 7, 11, 13, 17};

static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod) {
    __uint128_t res = ( __uint128_t ) a * b;
    return (uint64_t)(res % mod);
}

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod) {
    uint64_t result = 1;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

static int miller_rabin_pass(uint64_t n, uint64_t d, int s, uint64_t a) {
    uint64_t x = pow_mod(a, d, n);
    if (x == 1 || x == n - 1)
        return 1;
    for (int r = 1; r < s; ++r) {
        x = mul_mod(x, x, n);
        if (x == n - 1)
            return 1;
    }
    return 0;
}

static int is_prime(uint64_t n) {
    if (n < 2)
        return 0;
    for (size_t i = 0; i < sizeof(small_primes)/sizeof(small_primes[0]); ++i) {
        uint64_t p = small_primes[i];
        if (n == p)
            return 1;
        if (n % p == 0)
            return 0;
    }
    uint64_t d = n - 1;
    int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }
    for (size_t i = 0; i < sizeof(mr_bases)/sizeof(mr_bases[0]); ++i) {
        uint64_t a = mr_bases[i];
        if (a % n == 0)
            continue;
        if (!miller_rabin_pass(n, d, s, a))
            return 0;
    }
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long long ll = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    uint64_t n = (uint64_t) ll;
    if (n > MAX_INPUT) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");
    return 0;
}
